CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,email TEXT NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'operator',email_verified BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE (organization_id,email));
CREATE TABLE IF NOT EXISTS refresh_tokens (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name TEXT NOT NULL,domain TEXT,industry TEXT,acv NUMERIC DEFAULT 0,intent_score NUMERIC DEFAULT 0,physical_intervention_score NUMERIC DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,name TEXT NOT NULL,title TEXT,email TEXT,phone TEXT,address TEXT,address_status TEXT DEFAULT 'unknown',persona_type TEXT,intent_score NUMERIC DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS signals (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,account_id TEXT REFERENCES accounts(id) ON DELETE CASCADE,contact_id TEXT REFERENCES contacts(id) ON DELETE CASCADE,signal_type TEXT NOT NULL,signal_name TEXT NOT NULL,strength NUMERIC DEFAULT 0,payload JSONB DEFAULT '{}',occurred_at TIMESTAMPTZ DEFAULT now(),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS graph_edges (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,source_type TEXT NOT NULL,source_id TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,edge_type TEXT NOT NULL,weight NUMERIC DEFAULT 1,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name TEXT NOT NULL,budget NUMERIC DEFAULT 0,spent NUMERIC DEFAULT 0,status TEXT DEFAULT 'draft',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS touchpoints (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,campaign_id TEXT REFERENCES campaigns(id) ON DELETE SET NULL,contact_id TEXT,account_id TEXT,touch_type TEXT NOT NULL,status TEXT DEFAULT 'queued',tracking_code TEXT UNIQUE,qr_url TEXT,cost NUMERIC DEFAULT 0,fulfillment_provider TEXT,fulfillment_id TEXT,recipient_address TEXT,copy_generated TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS suppressions (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,type TEXT NOT NULL,value TEXT NOT NULL,reason TEXT,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(organization_id,type,value));
CREATE TABLE IF NOT EXISTS webhook_idempotency (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,provider TEXT NOT NULL,event_key TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(organization_id,provider,event_key));
CREATE TABLE IF NOT EXISTS webhook_dlq (id TEXT PRIMARY KEY,organization_id TEXT,payload JSONB,provider TEXT,error_message TEXT,attempts INT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS attribution_events (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,touchpoint_id TEXT NOT NULL,event_type TEXT NOT NULL,device_hash TEXT,anonymized_ip TEXT,location TEXT,timestamp TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_decision_audits (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,account_id TEXT,contact_id TEXT,decision JSONB NOT NULL,model TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,type TEXT NOT NULL,payload JSONB NOT NULL,status TEXT DEFAULT 'queued',attempts INT DEFAULT 0,error_message TEXT,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_accounts_org ON accounts(organization_id);
CREATE INDEX IF NOT EXISTS idx_contacts_org ON contacts(organization_id);
CREATE INDEX IF NOT EXISTS idx_signals_account ON signals(organization_id,account_id);
CREATE INDEX IF NOT EXISTS idx_touchpoints_code ON touchpoints(tracking_code);
CREATE INDEX IF NOT EXISTS idx_jobs_status ON jobs(organization_id,status);
